# Inglenook for hexyl: Inglenook Night.
# Source this from your profile. Needs hexyl 0.17 or newer.
# Palette 0.1.0, https://github.com/mookeyj79/Inglenook

# The offset column on the left.
export HEXYL_COLOR_OFFSET='#8f887f'
# The null byte.
export HEXYL_COLOR_NULL='#8f887f'
# Printable ASCII characters.
export HEXYL_COLOR_ASCII_PRINTABLE='#91bc88'
# Spaces, tabs and line breaks.
export HEXYL_COLOR_ASCII_WHITESPACE='#b1aa9e'
# Other ASCII bytes, such as control characters.
export HEXYL_COLOR_ASCII_OTHER='#da9f7c'
# Bytes above 0x7F.
export HEXYL_COLOR_NONASCII='#cb9cc6'
